package com.govweb.user; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/users") public class UserController {private final UserRepository repo; public UserController(UserRepository r){repo=r;} @GetMapping public List<User> all(){return repo.findAll().stream().peek(u->u.setPassword(null)).toList();} @DeleteMapping("/{id}") public void delete(@PathVariable Long id){repo.deleteById(id);} }
